#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    const char *in = argv[1];
    size_t in_len = strlen(in);
    if (in_len > 1024) in_len = 1024;
    char out[1025];
    size_t out_idx = 0;
    int have_output = 0;
    int pending_space = 0;
    for (size_t i = 0; i < in_len; ++i) {
        char c = in[i];
        int is_ws = (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f');
        if (is_ws) {
            if (have_output) pending_space = 1;
        } else {
            if (pending_space && out_idx > 0) {
                out[out_idx++] = ' ';
                pending_space = 0;
            }
            out[out_idx++] = c;
            have_output = 1;
        }
    }
    out[out_idx] = '\0';
    if (out_idx == 0) puts("EMPTY"); else puts(out);
    return 0;
}
